from control import OpenttdControl
from typing import Any, Dict, List, Optional, Type

from openttd_types import CompanyID


class CompanyReq:
    # name: str
    # president_name: str
    # president_gender: Gender
    # loan_amount: Money
    # max_loan_amount: Money
    # loan_interval: Money
    # bank_balance: Money
    # company_hq: TileIndex
    # auto_renew_status: bool
    # auto_renew_months: int
    # auto_renew_money: Money

    control: OpenttdControl
    company_id: CompanyID

    def __init__(self, control: OpenttdControl) -> None:
        self.control = control
        self.company_id = control.company_id

    async def query_name(self, company_id = None) -> str:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_company_name", params={"company_id": company_id})

    async def query_president_name(self, company_id = None) -> str:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_president_name", params={"company_id": company_id})

    async def query_president_gender(self, company_id = None) -> int:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_president_gender", params={"company_id": company_id})

    async def query_loan_amount(self) -> int:
        return await self.control.query("get_loan_amount")

    async def query_max_loan_amount(self) -> int:
        return await self.control.query("get_max_loan_amount")

    async def query_loan_interval(self) -> int:
        return await self.control.query("get_loan_interval")

    async def query_bank_balance(self, company_id = None) -> int:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_bank_balance", params={"company_id": company_id})

    async def query_company_hq(self, company_id = None) -> int:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_company_hq", params={"company_id": company_id})

    async def query_auto_renew_status(self, company_id = None) -> int:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_auto_renew_status", params={"company_id": company_id})

    async def query_auto_renew_months(self, company_id = None) -> int:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_auto_renew_months", params={"company_id": company_id})

    async def query_auto_renew_money(self, company_id = None) -> int:
        if company_id == None:
            company_id = self.company_id
        return await self.control.query("get_auto_renew_money", params={"company_id": company_id})

