    switch (key) {
        case "is_mine": {
            return AICompany.IsMine(params.company_id.tointeger());
            break;
        }
        case "set_name": {
            return AICompany.SetName(params.name);
            break;
        }
        case "set_president_name": {
            return AICompany.SetPresidentName(params.name);
            break;
        }
        case "set_president_gender": {
